// Cotizador simple: dias de rodaje x tarifa segun tipo de proyecto.
const { dias = 1, tipo = 'corporativo' } = $input.first().json;
const tarifas = { corporativo: 1200, ficcion: 2400, documental: 1600 };
const dia = tarifas[tipo] ?? tarifas.corporativo;
return [{ json: { tipo, dias, total_eur: dia * dias,
  desglose: `${dias} dias x ${dia} EUR` } }];
